using UnityEngine;
public class WoodlandFootPlacement:MonoBehaviour {
 public WoodlandCompanion companion;public Transform leftHip,leftKnee,leftFoot,rightHip,rightKnee,rightFoot;public float soleOffset=.035f;
 void LateUpdate(){if(!companion||!companion.animator.enabled||companion.anatomy&&companion.anatomy.Incapacitated)return;Place(leftHip,leftKnee,leftFoot);Place(rightHip,rightKnee,rightFoot);}
 void Place(Transform hip,Transform knee,Transform foot){if(!hip||!knee||!foot)return;Vector3 origin=foot.position+Vector3.up*.25f;if(!Physics.Raycast(origin,Vector3.down,out var hit,.65f,~0,QueryTriggerInteraction.Ignore)||hit.normal.y<.65f)return;float error=hit.point.y+soleOffset-foot.position.y;if(error<-.08f||error>.22f)return;float weight=Mathf.Clamp01(1-Mathf.Abs(error)/.26f)*.7f;Vector3 target=foot.position+Vector3.up*error*weight;Vector3 root=hip.position,joint=knee.position,end=foot.position;float a=Vector3.Distance(root,joint),b=Vector3.Distance(joint,end),d=Mathf.Clamp(Vector3.Distance(root,target),.001f,a+b-.001f);Vector3 axis=(target-root).normalized;Vector3 bend=Vector3.ProjectOnPlane(joint-root,axis).normalized;if(bend.sqrMagnitude<.01f)bend=companion.transform.forward;float along=(a*a+d*d-b*b)/(2*d);Vector3 desiredKnee=root+axis*along+bend*Mathf.Sqrt(Mathf.Max(0,a*a-along*along));hip.rotation=Quaternion.FromToRotation(joint-root,desiredKnee-root)*hip.rotation;knee.rotation=Quaternion.FromToRotation(foot.position-knee.position,target-knee.position)*knee.rotation;foot.rotation=Quaternion.Slerp(foot.rotation,Quaternion.FromToRotation(foot.up,hit.normal)*foot.rotation,.25f);}
}
